import Foundation

@main
enum ModuleInitializerInjector {
  static func main() throws {
    guard CommandLine.arguments.count == 2 else {
      throw CocoaError(.fileWriteInvalidFileName)
    }
    let destination = URL(fileURLWithPath: CommandLine.arguments[1])
    let source = """
    // Generated by EmacsSwiftModule. Do not edit.
    @_spi(ModuleEntry) import EmacsSwiftModule

    @c(emacs_module_init)
    public func initializeEmacsModule(_ runtime: UnsafeMutableRawPointer) -> Int32 {
      initializePlugin(type(of: createPlugin()), runtime: runtime)
    }
    """
    try source.write(to: destination, atomically: true, encoding: .utf8)
  }
}
